begin;
do $$declare w uuid:=gen_random_uuid();u uuid:=gen_random_uuid();o uuid;p uuid;r jsonb;n int;begin
 insert into public.workspaces(id,name) values(w,'Disposable regression test');
 insert into auth.users(id) values(u);
 insert into public.profiles(id,workspace_id,username,role) values(u,w,'test-'||u,'admin');
 insert into public.settings(workspace_id) values(w);
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.merge_sheet(w,'[{"code":"A","name":"Test A","phone":"+201000000001","status":"new","createdAt":null},{"code":"B","name":"Test B","phone":"+201000000002","status":"confirmed"}]');
 select id into o from public.orders where workspace_id=w and code='A';select id into p from public.orders where workspace_id=w and code='B';
 perform public.merge_sheet(w,'[{"code":"A","name":"Test A","phone":"+201000000001","status":"confirmed"}]');
 if (select status from public.orders where id=o)<>'confirmed' then raise exception 'Sheet confirmation failed';end if;
 if (select created_at from public.orders where id=o) is not null then raise exception 'Unknown dates were fabricated';end if;
 insert into storage.objects(bucket_id,name) values('waybills',w||'/test.png');
 r:=public.accept_bill(o,'EN012345678EG',w||'/test.png',repeat('a',64),'test.png');if not (r->>'ok')::boolean then raise exception 'First bill failed';end if;
 r:=public.accept_bill(o,'EN012345678EG',w||'/test.png',repeat('a',64),'test.png');if not (r->>'duplicate')::boolean then raise exception 'Duplicate was not rejected';end if;
 r:=public.accept_bill(p,'EN012345678EG',w||'/test.png',repeat('a',64),'test.png','update');if not (r->>'conflict')::boolean then raise exception 'Cross-order duplicate reassigned';end if;
 r:=public.accept_bill(o,'EN012345678EG',w||'/test.png',repeat('a',64),'renamed.png','update');if not (r->>'ok')::boolean then raise exception 'Explicit replacement failed';end if;
 if (select count(*) from public.waybills where workspace_id=w)<>1 then raise exception 'Duplicate bill inserted';end if;
 perform public.merge_sheet(w,'[{"code":"A","name":"Test A","phone":"+201000000001","status":"confirmed"}]');
 if (select status from public.orders where id=o)<>'shipped' then raise exception 'Sheet regressed shipment';end if;
 insert into public.postal_events(workspace_id,event_key,tracking,kind,text,source,received_at) values(w,'delivery','EN012345678EG','delivered','synthetic delivery','test','2026-01-02'),(w,'attempt','EN012345678EG','attempt','synthetic attempt','test','2026-01-03'),(w,'unmatched','EN012345679EG','delivered','synthetic unmatched','test','2026-01-01');
 n:=public.apply_postal(w);if n<>2 then raise exception 'Wrong matching count';end if;
 if (select status from public.orders where id=o)<>'delivered' or (select carrier_status from public.orders where id=o)<>'تم التسليم للمرسل إليه' then raise exception 'Later attempt regressed delivery';end if;
 if (select count(*) from public.postal_events where workspace_id=w and order_id is null)<>1 then raise exception 'Unmatched evidence was lost';end if;
 if public.apply_postal(w)<>0 then raise exception 'Reapplication was not idempotent';end if;
 if (select retention_days from public.settings where workspace_id=w) is not null then raise exception 'Retention enabled without selection';end if;
end$$;
rollback;
select 'All reconciliation checks passed; test data rolled back' as result;
